begin
  var g := Self.GetEnumerator();
  if g.MoveNext() then
  begin  
    Write(g.Current);
    while g.MoveNext() do
      if delim <> '' then
        Write(delim, g.Current)
      else Write(g.Current);
  end;  
  Result := Self; 
end;

