function MatrEqual<T>(a, b: array [,] of T): boolean;
begin
  var (m1,n1) := a.Size;
  var (m2,n2) := b.Size;
  Result := True;
  if (m1<>m2) or (n1<>n2) then
    Result := False
  else
    for var i:=0 to m1-1 do
    for var j:=0 to n1-1 do
      if a[i,j]<>b[i,j] then
      begin
        Result := False;
        exit;
      end;
end;

type
  AdjGroupClass<T> = class
  private 
    cur: T;
    enm: IEnumerator<T>;
    fin: boolean;
  public 
    constructor Create(a: sequence of T);
    begin
      enm := a.GetEnumerator();
      fin := enm.MoveNext;
      if fin then
        cur := enm.Current;
    end;

    function TakeGroup: sequence of T;
    begin
      yield cur;
      fin := enm.movenext;
      while fin do
      begin
        if enm.current = cur then
          yield enm.current
        else
        begin
          cur := enm.Current;
          break;
        end;
        fin := enm.movenext;
      end;  
    end;
  end;

function IncrementalSeq(Self: sequence of integer): sequence of integer; 
begin
  var iter := Self.GetEnumerator();
  if iter.MoveNext() then
  begin
    var prevItem := iter.Current;
    while iter.MoveNext() do
    begin
      var nextItem := iter.Current;
      yield nextItem - prevItem;
      prevItem := nextItem;
    end
  end
end;

function CreateSliceFromList<T>(Self: List<T>; from, step, count: integer): List<T>;
begin
  Result := new List<T>(count);

  var f := from;
  loop count do
  begin
