    f += step;
  end;
end;

function NextCombHelper(ind: array of integer; m,n: integer): boolean;
begin
  for var i:=m-1 downto 0 do
    if ind[i] < n - m + i then
    begin
      ind[i] += 1;
      for var j:=i to m-1 do 
        ind[j+1] := ind[j] + 1;
      Result := True;
      exit
    end;
  Result := False;  
end;

function NextPermutation(a: array of integer): boolean;
begin
  var n := a.Length;
  var j := n - 2;
  while (j <> -1) and (a[j] >= a[j + 1]) do
    j -= 1;
  if j = -1 then
  begin  
    Result := False;  
    exit;
  end;  
  var k := n - 1;
  while a[j] >= a[k] do 
    k -= 1;
  Swap(a[j], a[k]);
  Reverse(a,j+1,n-1-j);
  Result := True;
end;

